args.command:
mkdir -p ~/w; cat > ~/w/blobs.py <<'EOF'
import sys
from PIL import Image
im=Image.open(sys.argv[1]).convert('L'); W,H=im.size; px=im.load()
seen=set(); out=[]
for y in range(H):
  for x in range(W):
    if px[x,y]<70 and (x,y) not in seen:
      st=[(x,y)]; seen.add((x,y)); pts=[]
      while st:
        a,b=st.pop(); pts.append((a,b))
        for c,d in((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
          if 0<=c<W and 0<=d<H and (c,d) not in seen and px[c,d]<70:
            seen.add((c,d)); st.append((c,d))
      if len(pts)<20000:
        n=len(pts); cx=sum(p[0] for p in pts)/n; cy=sum(p[1] for p in pts)/n
        out.append((round(cx,2),round(cy,2),n))
for o in out: print(*o)
EOF
python3 ~/w/blobs.py ~/captures/wrist_002.png

